/usr/bin/bash -lc "python - <<'PY'
import re,collections,yaml
p='candidate/statement-ledger.md'; lines=open(p).read().splitlines(); claims=yaml.safe_load(open('lean/claims.yaml'))['claims']; cov=yaml.safe_load(open('lean/coverage.yaml')); doc=yaml.safe_load(open('docs/coverage-scope-tex.yaml'))
rows=[]; bad=[]; ix=[]
for n,l in enumerate(lines,1):
 if not l.startswith('|'):continue
 c=[s.strip() for s in re.split(r'(?<"'!'"\\\\)\\|',l)[1:-1]]
 if n>=459 and len(c)>1 and re.fullmatch(r'"'`Stratonovich'"\\w+\\.["'^`]+`'"',c[1]):
  if len(c)"'!=4:bad.append((n,len(c)))
  rows.append((n,c[1][1:-1],c[0]))
 if 244<=n<=455:ix.append((n,c))
rc=collections.Counter(x[1] for x in rows); cc=collections.Counter(c['"'decl'] for c in claims)
print('TABLE TOTAL',len(rows),'LABELLED',sum(not r[2].startswith('no direct label') for r in rows),'UNLABELLED',sum(r[2].startswith('no direct label') for r in rows)); print('CLAIMS KINDS',collections.Counter(c['kind'] for c in claims));print('BAD CELLS',bad);print('CLAIMS DIFF',list((cc-rc).items()),list((rc-cc).items()));print('REPEAT ROWS',[r for r in rc.items() if r[1]"'!=1]);
# Index full names are usually module abbreviated; exact matches of suffix tokens.
found=collections.defaultdict(list);unknown=[]
for n,cells in ix:
 if len(cells)!=3:continue
 for token in re.findall(r'"'"'`([''^`]+)`'"',cells[1]):
  matches=[d for d in rc if d==token or d.endswith('.'+token)]
  if len(matches)==1:found[matches[0]].append((n,cells[0]))
  elif token not in ['Lean declarations']:unknown.append((n,token,len(matches)))
print('INDEX MISSING',[(d,n) for n,d,l in rows if not found[d]]);print('INDEX REPEATS',[(d,v) for d,v in found.items() if len(v)"'!=1]);print('"'INDEX UNKNOWN',unknown)
print('SCOPE ASCII MISMATCH',[(r['label'],r['ascii'],next((s.get('conclusion_scope') for s in cov['rows'] if s['paper']['label']==r['label']),None)) for r in doc['rows'] if r['ascii']"'!=next((s.get('"'conclusion_scope') for s in cov['rows'] if s['paper']['label']==r['label']),None)])
PY"

